    const repairTerms = ['hasar','zarar','tamir','onar','yapar','yapilir','yaptir','karsila','karsilan','ode','odeme','masraf','kaporta','boya','servis','ariz','zarari karsila'];
    const otherPartyTerms = ['karsi taraf','diger arac','bana carpti','bana vurdu','karsi tarafin','baskasinin araci','ucuncu kisi','diger surucu'];

