    const mentionsTraffic = has('trafik','zorunlu trafik','trafik sigortasi','trafik policem','trfik');
    const mentionsOtherParty = otherPartyTerms.some(term => phraseMatch(q, term));
    const explicitOwnVehiclePhrases = ['kendi arac','benim arac','aracim','aracimin','aracimi','arabam','arabamin','arabami','otomobilim','kendi arab','benim araba','aracimda','arabamda'];
