    const asksCoverage = has('karsilar','karsilarmi','karsiliyor','karsiliyor mu','karsilanir','karsilanirmi','karsiliyo','karsiliyo mu','oder','odermi','oduyor','odeme','yapar','yaparmi','yapilir','yaptir','yaptirir','yaptirirmi','tamir','onar','kapsar','masraf','hasar','zarar','benim arabam','aracim');

